+    @Before
+    public void setUpIndex() throws Exception {
+        var num_primaries = randomIntBetween(1, 4);
+        createIndex(
+            indexName,
+            Settings.builder()
+                .put(IndexMetadata.SETTING_NUMBER_OF_SHARDS, num_primaries)
+                .put(IndexMetadata.SETTING_NUMBER_OF_REPLICAS, 0)
